import { cleanup, render, screen } from '@solidjs/testing-library'
import { afterEach, describe, expect, it } from 'vitest'
import { scanSources } from '../test-utils/source-scan'
import { createTestApp } from '../test-utils/app'
import { stepById } from '../flow/registry'
import { StepScreen } from './steps'

/**
 * The step screens' *structure* (T24–T32).
 *
 * The flow tests drive the screens and assert what the numbers say; these assert
 * how the screen is built, because "what the user sees" is not the same thing as
 * "what the JSX says".
 *
 * That distinction is not academic. Solid compiles each screen into a
 * `<template>`, so the browser's HTML parser gets a vote: a `<ul>` written inside
 * a `<p>` is closed by the parser, the stray `</p>` becomes an empty paragraph,
 * and the child indices the compiler generated no longer address the nodes it
 * thinks they do. The result was a step 5 whose figures, headings and paragraphs
 * rendered in an order that appeared nowhere in the source. Nothing in the DOM
 * is wrong on its own — every element is present and correct — so only an
 * assertion about *order* can see it.
 */

/** Render a registered step on its own, as the engine would. */
function renderStep(id: Parameters<typeof stepById>[0]): HTMLElement {
  const app = createTestApp()
  const { container } = render(() => (
    <StepScreen
      step={stepById(id)}
      engine={app.engine}
      printers={app.printers}
      settings={app.settings}
    />
  ))
  return container
}

/** The step's own content column: the direct parent of its measurement group. */
function contentColumn(container: HTMLElement): Element {
  const fieldset = container.querySelector('fieldset')
  if (fieldset?.parentElement == null) {
    throw new Error('Expected the step to render a measurement group')
  }
  return fieldset.parentElement
}

afterEach(cleanup)

describe('the measure step (Q5)', () => {
  it('renders the instructions in the order they are written', () => {
    const container = renderStep('Q5')

    const order = Array.from(contentColumn(container).children).map((element) =>
      element.tagName.toLowerCase(),
    )

    expect(order).toEqual([
      'h3', // Before you measure
      'div', // the warning box
      'h3', // How to measure the inner jaws
      'p',
      'h4', // Correct
      'ul', // the three seating rules — a sibling of the heading, not inside a <p>
      'figure',
      'figure',
      'figure',
      'h4', // Incorrect examples
      'p', // introduces the first wrong example
      'figure',
      'p', // introduces the second wrong example
      'figure',
      'h3', // Measuring the dimensions
      'p',
      'fieldset', // the measurements themselves
    ])
  })

  it('points each incorrect example out before showing it', () => {
    // The symptom the order assertion above guards, named directly: before the
    // fix, both figures were hoisted above the heading and paragraphs that
    // explain them.
    renderStep('Q5')

    const heading = screen.getByRole('heading', { name: 'Incorrect examples' })
    const captions = screen
      .getAllByRole('img')
      .map((img) => img.getAttribute('alt') ?? '')
      .filter((alt) => alt.startsWith('Incorrect:'))

    expect(captions).toHaveLength(2)
    for (const caption of captions) {
      const figure = screen.getByAltText(caption)
      expect(
        heading.compareDocumentPosition(figure) & Node.DOCUMENT_POSITION_FOLLOWING,
      ).toBeTruthy()
    }
  })

  it('gives each measurement its own diagram on its own row', () => {
    const container = renderStep('Q5')
    const fieldset = container.querySelector('fieldset')
    const column = fieldset?.querySelector('.stack')
    if (column == null) {
      throw new Error('Expected the measurement group to hold a column')
    }

    // Field, diagram, field, diagram, then the two photos of the calipers in
    // use: one per row, so every image is the full width of the step. The
    // two-up grid this replaced halved each diagram, which made the jaw
    // placement — the only thing the diagram is for — unreadable.
    const rows = Array.from(column.children).map((element) => element.tagName.toLowerCase())
    expect(rows).toEqual(['div', 'figure', 'div', 'figure', 'div'])

    // The diagram follows the field it belongs to, rather than the two
    // diagrams sitting together below both fields.
    const firstRow = column.children[0].textContent ?? ''
    expect(firstRow).toContain('X outer (across both end walls)')
    const firstCaption = column.children[1].textContent ?? ''
    expect(firstCaption).toContain('Where the outer measurement goes.')

    // No grid remains for the layout to fall back into.
    expect(container.querySelectorAll('.measurement-grid')).toHaveLength(0)
  })
})

